DROP PROCEDURE IF EXISTS alignment_diag_ascii;
DELIMITER $$
CREATE PROCEDURE alignment_diag_ascii() BEGIN DECLARE q1 VARCHAR(512) CHARACTER SET ascii DEFAULT '6c0eeb86-bda6-5055-b3cf-81a8bf523191';DECLARE q2 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Knows';DECLARE q3 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Knows';DECLARE q4 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person';DECLARE q5 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person';DECLARE q6 VARCHAR(512) CHARACTER SET ascii DEFAULT '6c0eeb86-bda6-5055-b3cf-81a8bf523191';DECLARE q7 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Knows';DECLARE q8 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Knows';DECLARE q9 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person';DECLARE q10 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person';DECLARE q11 VARCHAR(512) CHARACTER SET ascii DEFAULT '6c0eeb86-bda6-5055-b3cf-81a8bf523191';DECLARE q12 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person';DECLARE q13 VARCHAR(512) CHARACTER SET utf8mb4 DEFAULT 'Person'; SELECT 'ascii';SHOW SESSION STATUS WHERE Variable_name IN('Handler_read_rnd_next','Handler_read_key','Handler_read_next','Select_scan');EXPLAIN FORMAT=JSON SELECT n.id,e.id FROM (SELECT e.* FROM anchors e WHERE e.src=q1 AND e.kind='EdgeAnchor' AND (e.arch_type=q2 OR e.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q3)) AND (e.dst_type IS NULL OR e.dst_type=q4 OR e.dst_type IN(SELECT type_name FROM graph_types WHERE ancestor=q5)) UNION ALL SELECT e.* FROM anchors e WHERE e.dst=q6 AND e.undirected=1 AND e.src<>e.dst AND e.kind='EdgeAnchor' AND (e.arch_type=q7 OR e.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q8)) AND (e.src_type IS NULL OR e.src_type=q9 OR e.src_type IN(SELECT type_name FROM graph_types WHERE ancestor=q10))) e JOIN anchors n ON n.id=CASE WHEN e.src=q11 THEN e.dst ELSE e.src END AND n.kind='NodeAnchor' AND (n.arch_type=q12 OR n.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q13)) ORDER BY e.seq,e.id;SELECT n.id,e.id FROM (SELECT e.* FROM anchors e WHERE e.src=q1 AND e.kind='EdgeAnchor' AND (e.arch_type=q2 OR e.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q3)) AND (e.dst_type IS NULL OR e.dst_type=q4 OR e.dst_type IN(SELECT type_name FROM graph_types WHERE ancestor=q5)) UNION ALL SELECT e.* FROM anchors e WHERE e.dst=q6 AND e.undirected=1 AND e.src<>e.dst AND e.kind='EdgeAnchor' AND (e.arch_type=q7 OR e.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q8)) AND (e.src_type IS NULL OR e.src_type=q9 OR e.src_type IN(SELECT type_name FROM graph_types WHERE ancestor=q10))) e JOIN anchors n ON n.id=CASE WHEN e.src=q11 THEN e.dst ELSE e.src END AND n.kind='NodeAnchor' AND (n.arch_type=q12 OR n.arch_type IN(SELECT type_name FROM graph_types WHERE ancestor=q13)) ORDER BY e.seq,e.id;SHOW SESSION STATUS WHERE Variable_name IN('Handler_read_rnd_next','Handler_read_key','Handler_read_next','Select_scan'); END$$
DELIMITER ;
CALL alignment_diag_ascii();
